BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-20963'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='3A0404' OR source_url ~ '[?&]id=20963(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='02b49f38-627b-4149-bd65-36e58f340404' OR slug='sam-direct-sale-showroom-phanit-phatthana-phanat-nikhom-3a0404' OR (abs(latitude-13.454414)<0.0001 AND abs(longitude-101.188402)<0.0001 AND abs(land_area_sqm-804)<1)) THEN RAISE NOTICE 'SAM 3A0404 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, title, description, sale_price, price_negotiable, land_area_sqm, total_floors, bathroom_count, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('02b49f38-627b-4149-bd65-36e58f340404', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'retail_space', 'business', 'sale', 'whole_property', 'ขายตรง SAM โชว์รูม 2 ชั้น พนัสนิคม ถนนพาณิชพัฒนา 1 ที่ดิน 201 ตร.ว.', 'อาคารโชว์รูมแสดงสินค้า 2 ชั้น ไม่ปรากฏเลขทะเบียน ถนนพาณิชพัฒนา 1 ตำบลพนัสนิคม อำเภอพนัสนิคม จังหวัดชลบุรี ที่ดิน 2 แปลงติดต่อกัน โฉนดเลขที่ 19148 และ 19161 จำนวน 2 ฉบับ เนื้อที่รวม 2 งาน 1 ตร.ว. หรือ 201 ตร.ว. (804 ตร.ม.) ต้นทางระบุ 2 ห้องน้ำ ราคาประกาศขายจาก SAM 6,921,000 บาท รหัสทรัพย์ 3A0404

ที่ดินรูปสี่เหลี่ยมผืนผ้า ติดถนน 3 ด้าน ด้านทิศเหนือและทิศใต้กว้างด้านละประมาณ 20 เมตร ด้านทิศตะวันตกลึกประมาณ 44 เมตร ต้นทางระบุผังเมืองสีส้มและย่านที่อยู่อาศัย

รายการอาคารที่โอนต้องตรวจสอบ: SAM จดทะเบียนรับโอนเป็นอาคารโชว์รูมแสดงสินค้า 2 ชั้นไม่ปรากฏเลขทะเบียน แต่สำรวจพบอาคารแสดงสินค้าสูง 2 ชั้นและอาคารป้อมยาม SAM ระบุว่าจะโอนกรรมสิทธิ์ตามรายการสิ่งปลูกสร้างที่จดทะเบียนรับโอนทางทะเบียนเท่านั้น ผู้ซื้อควรขอรายการโอนและยืนยันสถานะป้อมยาม แบบอาคารและใบอนุญาตก่อนซื้อ

ทางเข้าเป็นประเด็นสำคัญ: ถนนพาณิชพัฒนา 1 เป็นถนนส่วนบุคคลในโครงการแบ่งขายที่ดินเอกชน SAM ระบุว่ามีการใช้เข้าออกโดยเปิดเผยมานานเกิน 10 ปี และเป็นสาธารณูปโภคที่จัดให้มีขึ้นซึ่งตกอยู่ในภาระจำยอมเพื่อประโยชน์แก่ที่ดินในโครงการ ผิวคอนกรีตและเขตทางกว้างประมาณ 6 เมตร ผู้ซื้อควรตรวจหลักฐานสิทธิใช้ทาง ขอบเขต ผู้รับประโยชน์และการใช้จริงก่อนเสนอซื้อ ข้อมูลนี้ไม่ได้ยืนยันว่ามีการจดทะเบียนภาระจำยอมไว้แล้ว

ชื่อพื้นที่ในเอกสารสิทธิ์แตกต่างจากที่ตั้งหน้าเว็บ: โฉนดระบุตำบลบ้านช้าง (วัดกลาง) อำเภอพนัสนิคม (พนัศ) จังหวัดชลบุรี ขณะที่หน้า SAM ระบุตำบลพนัสนิคม ควรตรวจตำแหน่งแปลงและข้อมูลที่อยู่กับสำนักงานที่ดินให้ตรงกัน

สถานที่ใกล้เคียงตาม SAM ได้แก่ โรงเรียนเทศบาล 1 วัดพลับ ที่ว่าการอำเภอพนัสนิคม และสถานีตำรวจภูธรอำเภอพนัสนิคม การเดินทางใช้ถนนหนองซาก–พนัสนิคม (ทล.315) จากฉะเชิงเทรามุ่งหน้าบ้านบึง ผ่านโรงพยาบาลพนัสนิคม ถึงสี่แยกพนัสนิคม เลี้ยวซ้ายถนนเมืองเก่าประมาณ 1.2 กิโลเมตร เลี้ยวซ้ายถนนศรีวิชัย 200 เมตร แล้วเลี้ยวขวาถนนพาณิชพัฒนา 1 อีก 150 เมตร ทรัพย์อยู่ด้านขวามือ

หน้า SAM แสดงสถานะซื้อตรงและราคาข้างต้น ณ วันที่ 11 กันยายน 2569 ติดต่อ SAM โทร 02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส 3A0404 เพื่อยืนยันสถานะพร้อมขาย ราคา การนัดชม รายการอาคารและสิทธิใช้ทาง ทรัพย์ใกล้เคียง 3A0403 และ 3A0405 ที่ต้นทางกล่าวถึงไม่ได้รวมในประกาศนี้

พิกัด 13.454414, 101.188402 ดึงจากลิงก์นำทาง SAM และตรงกับ Google Map ภาพภายนอกมีวันที่ 19 สิงหาคม 2565 และภาพทางเข้าอาคารกับภายในมีวันที่ 8 พฤษภาคม 2567 รวม 16 ภาพ มีผังแปลง ผังอาคารและแผนที่ ต้นทางไม่ระบุพื้นที่ใช้สอย จำนวนที่จอดรถ อายุอาคาร หรือสถานะผู้ครอบครอง ต้องยืนยันสภาพและการใช้ประโยชน์ที่อนุญาตก่อนซื้อ', 6921000, false, 804, 2, 2, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, 'อาคารโชว์รูม ไม่ปรากฏเลขทะเบียน ถนนพาณิชพัฒนา 1', 'โฉนดระบุตำบลบ้านช้าง (วัดกลาง) ต้องตรวจชื่อที่ตั้ง', 'ถนนพาณิชพัฒนา 1', 13.454414, 101.188402, 'ชลบุรี', 'พนัสนิคม', 'พนัสนิคม', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-direct-sale-showroom-phanit-phatthana-phanat-nikhom-3a0404') RETURNING id INTO property_listing_id;
