INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=20963&keyref=6007684', '3A0404', now(), 'Official source captured 2026-09-11. THB 6,921,000; two plots 201 sq.wah; two-storey showroom, two bathrooms. Transfer restricted to registered structures; surveyed guardhouse status unconfirmed. Private project road with source-reported over-ten-year open use and utility easement, not represented as registered. Title/website locality difference disclosed. Sixteen source photos dated 2022-08-19 and 2024-05-08. Nearby listing 1354/3A0403 mentions this code but is different by source/title/area/coordinates. No exact duplicate. Navigation/map agree.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'SAM Direct Sale: 2-Storey Phanat Nikhom Showroom, THB 6.921M', 'Two-storey showroom without a stated registration number on Phanit Phatthana 1 Road, Phanat Nikhom subdistrict and district, Chon Buri. Two adjoining plots, Chanote 19148 and 19161, total 201 sq.wah (804 sq.m.). SAM lists two bathrooms. Announced sale price THB 6,921,000; asset 3A0404.

Rectangular land with roads on three sides. North and south sides are approximately 20 metres each; the western depth is approximately 44 metres. SAM reports orange planning zoning and residential surroundings.

Registered acquisition lists a two-storey showroom without a registration number. Surveyed structures are a two-storey-high display building and a guardhouse. SAM states that transfer follows only the structures in its registered acquisition schedule. Verify the transfer list, guardhouse status, building plans and permits.

Phanit Phatthana 1 is a private road in a privately subdivided land project. SAM reports open use for access for over ten years and describes the road as a provided utility subject to an easement benefiting project land. Concrete carriageway and right of way are approximately six metres wide. Verify evidence, scope, beneficiaries and actual access before offering. The source does not establish that an easement has been registered.

Title location wording differs from the website: the deeds state Ban Chang (Wat Klang), Phanat Nikhom (Phanat), Chon Buri, while the page uses Phanat Nikhom subdistrict. Confirm parcel location and address with the Land Office.

Nearby source-listed places include Municipal School 1, Wat Phlap, the district office and police station. From Chachoengsao toward Ban Bueng on Highway 315, pass Phanat Nikhom Hospital, turn left at the intersection into Mueang Kao Road for 1.2 kilometres, left into Si Wichai Road for 200 metres, then right into Phanit Phatthana 1 for 150 metres; the property is on the right.

SAM showed direct-purchase status and this price on 11 September 2026. Contact 02-686-1888, sales@sam.or.th or LINE @samline, quoting 3A0404, to confirm availability, price, viewing, structures and access. Nearby 3A0403 and 3A0405 are separate assets and are not included.

Navigation and map agree on 13.454414, 101.188402. Exterior photos display 19 August 2022; entrance/interior photos display 8 May 2024. Sixteen images include plot/building plans and map. Usable area, parking, age and occupancy are not published; verify current condition and permitted use.', 'Showroom without stated registration number, Phanit Phatthana 1', 'Title locality: Ban Chang (Wat Klang); verify address', 'Phanit Phatthana 1 Road', 'Phanat Nikhom', 'Phanat Nikhom', 'Chon Buri', 'SAM Phanat Nikhom Showroom — THB 6.921M', 'SAM 3A0404: two-storey showroom, 201 sq.wah, roads on three sides, THB 6,921,000. Private access and transfer inventory disclosed.', 'published', 'ai_assisted', now(), 'sam direct sale: 2-storey phanat nikhom showroom, thb 6.921m two-storey showroom without a stated registration number on phanit phatthana 1 road, phanat nikhom subdistrict and district, chon buri. two adjoining plots, chanote 19148 and 19161, total 201 sq.wah (804 sq.m.). sam lists two bathrooms. announced sale price thb 6,921,000; asset 3a0404.

